package org.opentaint.jvm.sast.dataflow

import kotlinx.coroutines.runBlocking
import org.opentaint.common.sast.CommonAnalysisOptions
import org.opentaint.common.sast.dataflow.TaintAnalyzer
import org.opentaint.common.sast.rules.loadSemgrepRules
import org.opentaint.config.JavaDefaultConfigLoader
import org.opentaint.dataflow.ap.ifds.*
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.driver.*
import org.opentaint.dataflow.bidi.engine.*
import org.opentaint.dataflow.bidi.interp.*
import org.opentaint.dataflow.bidi.store.*
import org.opentaint.dataflow.jvm.ap.ifds.*
import org.opentaint.dataflow.jvm.ap.ifds.analysis.JIRAnalysisManager
import org.opentaint.dataflow.jvm.ap.ifds.analysis.JIRMethodGetDefault
import org.opentaint.dataflow.jvm.ap.ifds.taint.forBidirectionalCore
import org.opentaint.dataflow.jvm.bidi.JIRBidiAnalysis
import org.opentaint.dataflow.jvm.bidi.interp.PrescanLambdas
import org.opentaint.dataflow.jvm.ifds.JIRUnitResolver
import org.opentaint.ir.api.common.cfg.CommonInst
import org.opentaint.ir.api.jvm.JIRClassOrInterface
import org.opentaint.ir.api.jvm.JIRMethod
import org.opentaint.ir.api.jvm.cfg.JIRInst
import org.opentaint.ir.impl.features.usagesExt
import org.opentaint.jvm.graph.JApplicationGraphImpl
import org.opentaint.jvm.graph.JApplicationSingleExitGraph
import org.opentaint.jvm.sast.dataflow.rules.TaintConfiguration
import org.opentaint.jvm.sast.project.ProjectAnalysisOptions
import org.opentaint.jvm.sast.project.initializeProjectAnalysisContext
import org.opentaint.jvm.sast.project.rules.analysisConfig
import org.opentaint.jvm.sast.rules.JIRSemgrepRuleProvider
import org.opentaint.jvm.sast.util.locationChecker
import org.opentaint.project.JavaProject
import org.opentaint.semgrep.pattern.TaintRuleFromSemgrep
import org.opentaint.semgrep.pattern.conversion.JavaLanguageStrategy
import org.opentaint.dataflow.configuration.jvm.serialized.SerializedItem
import java.lang.reflect.InvocationTargetException
import java.nio.file.Path
import kotlin.time.Duration
import kotlin.time.Duration.Companion.seconds

/** Exact saved project + production single-doPost-root prescan and bidi run.
 * All observations delegate to production services. Reflection only supplies the
 * existing driverFactory/invokeRun observation seam and reads frozen cache rows.
 * No seed, initial, demand, cache, plan, or report is fabricated or rewritten.
 */
object ActualTrustJirEngineMain {
    private const val RULE = "java/security/insecure-design.yaml:trust-boundary-violation"
    private const val OWNER = "org.owasp.benchmark.testcode.BenchmarkTest01875"
    private fun selected(key: MethodKey) = (key.method as JIRMethod).enclosingClass.name == OWNER
    private fun <T> unwrap(body: () -> T): T = try { body() } catch (e: InvocationTargetException) { throw e.targetException }

    @JvmStatic fun main(args: Array<String>) {
        val projectFile = Path.of(System.getProperty("opentaint.audit.project",
            "/drive-testcomp/opentaint-go-rules/owasp-ci-investigation/project/project.yaml"))
        val ruleRoot = Path.of(System.getProperty("opentaint.audit.rules",
            "/drive-testcomp/opentaint-go-rules/opentaint-w3/rules/ruleset"))
        val common = CommonAnalysisOptions(semgrepRuleSet = listOf(ruleRoot), ifdsBidirectional = true,
            ifdsAnalysisTimeout = System.getProperty("opentaint.audit.engineSeconds", "120").toInt().seconds)
        val loaded = common.loadSemgrepRules(JavaLanguageStrategy())
        @Suppress("UNCHECKED_CAST")
        val generated = loaded.rulesWithMeta.map { it.first as TaintRuleFromSemgrep<SerializedItem> }
        val project = JavaProject.load(projectFile).resolve(projectFile.parent)
        initializeProjectAnalysisContext(project, ProjectAnalysisOptions(common = common)).use { context ->
            val cp = context.cp
            val cfg = TaintConfiguration(cp)
            JavaDefaultConfigLoader.loadConfig()?.let(cfg::loadConfig)
            val raw = JIRSemgrepRuleProvider(generated, cfg)
            val rules = StringConcatRuleProvider(context.analysisConfig(raw)).forBidirectionalCore()
            val main = JApplicationGraphImpl(cp, runBlocking { cp.usagesExt() })
            val graph = JIRSafeApplicationGraph(JApplicationSingleExitGraph(JTryBoundaryExceptionsApplicationGraph(main)))
            val locations = context.projectClasses.locationChecker()
            val units = JIRTaintAnalyzer.Companion.PackageUnitResolver(locations)
            val getters = JIRMethodGetDefault(object : JIRMethodGetDefault.Configuration {
                override fun enableDefaultPropagationForClass(cls: JIRClassOrInterface) = !locations.isProjectClass(cls)
            })
            val params = JIRAnalysisManager.Params(defaultGetModel = getters,
                aliasAnalysisParams = JIRLocalAliasAnalysis.Params(aliasAnalysisInterProcCallDepth = common.experimentalAAInterProcCallDepth))
            val root = checkNotNull(cp.findClassOrNull(OWNER)).declaredMethods.single { it.name == "doPost" }
            var driver: IterationDriver? = null
            var report: Report? = null
            val analyzer = object : TaintAnalyzer<JIRMethod, JIRInst>(common.taintAnalyzerOptions()) {
                private val actualManager by lazy { JIRAnalysisManager(cp, refManager, rules, params = params) }
                override fun analysisGraph() = graph
                override fun analysisManager() = actualManager
                override fun unitResolver(): JIRUnitResolver = units
                override fun bidiEntry(): BidiEntry {
                    val factory: (IterationPolicy, SharedObjects, Duration) -> IterationDriver = { policy, shared, budget ->
                        fun fact(p: PathFact) = "${p.base}${p.path.map(shared.ap.accessors::accessor)}:${p.tail}:" +
                            when (val m = p.mark) { is MarkSlot.Concrete -> shared.ap.marks.name(m.mark); else -> m.toString() }
                        fun packet(pr: PremiseKey, f: Facts) = "premise=${pr.members.map { fact(it.toPattern().fact) }} " +
                            "layer=${f.layer} facts=${shared.ops.leaves(f).map { fact(it.fact) }.toList()}"
                        fun relevant(f: Facts) = f is Reach || f is FlowTree || shared.ops.leaves(f).any {
                            (it.fact.mark as? MarkSlot.Concrete)?.let { m -> shared.ap.marks.name(m.mark).startsWith(RULE + ";") } == true }
                        fun cache(label: String, run: Int, rows: Iterable<NormalRuleContributorRow>) {
                            for (row in rows) if (selected(row.key.owner.method)) {
                                val pr = row.input.premise
                                val f = row.input.facts ?: continue
                                if (!relevant(f)) continue
                                val rule = row.key.rule as? NormalRuleDescriptor.Predicate
                                println("ENGINE_CACHE $label run=$run method=${row.key.owner.method.method.name} scope=${row.key.owner.scope} " +
                                    "kind=${rule?.occurrence?.kind} ordinal=${rule?.occurrence?.ordinal} at=${row.key.site.statement.location.index} " +
                                    "stage=${row.key.site.stageOrdinal} leaf=${row.leaf} ${packet(pr, f)}")
                            }
                        }
                        val currentPoint = ThreadLocal<String>()
                        val probeActors = java.util.concurrent.ConcurrentHashMap<MethodKey, RunMethodAnalyzer>()
                        val invoke: (RunConfig, SharedObjects, Duration) -> RunResult<RunMethodAnalyzer> = { config, state, timeout ->
                            println("ENGINE_CONFIG run=${config.index} direction=${config.direction} limit=${config.fieldLimit} seededSources=${config.seededSources} seeds=${config.seeds.size}")
                            cache("PREVIOUS", config.index, state.normalRuleContributors.snapshot().allRows())
                            val local = MethodLocalServicesFactory { core ->
                                val actual = RunMethodLocalServices(core)
                                object : MethodLocalServices by actual {
                                    override fun addMarkRequest(premise: InitialAp, mark: TaintMark) {
                                        if (selected(core.key) && shared.ap.marks.name(mark).startsWith(RULE + ";"))
                                            println("ENGINE_MARK_REQUEST run=${config.index} method=${core.key.method.name} scope=${core.scope} " +
                                                "origin=${fact(premise.toPattern().fact)} mark=${shared.ap.marks.name(mark)} current=${currentPoint.get()}")
                                        actual.addMarkRequest(premise,mark)
                                    }
                                    override fun addMarkRequests(premise: InitialAp, marks: RequestMarkSet) {
                                        if (selected(core.key)) marks.forEachMark { mark ->
                                            if (shared.ap.marks.name(mark).startsWith(RULE + ";"))
                                                println("ENGINE_MARK_REQUEST_BULK run=${config.index} method=${core.key.method.name} scope=${core.scope} " +
                                                    "origin=${fact(premise.toPattern().fact)} mark=${shared.ap.marks.name(mark)} current=${currentPoint.get()}")
                                        }
                                        actual.addMarkRequests(premise,marks)
                                    }
                                    override fun sourcePredicateActionsAt(source: SourceRuleOccurrence, premise: PremiseKey, facts: Facts,
                                        node: CommonInst, statementEdge: Boolean, at: OperationInput,
                                        sink: (PremiseKey, Facts, ActionId?) -> Unit) {
                                        val watch = selected(core.key) && source.predicate.leaves.any {
                                            (it.fact.mark as? MarkSlot.Concrete)?.let { m -> shared.ap.marks.name(m.mark).startsWith(RULE + ";") } == true }
                                        val tag = if (core.key.method.name == "doSomething" && node.location.index == 1)
                                            "ENGINE_SOURCE15" else "ENGINE_TRUST_SOURCE"
                                        val where = "method=${core.key.method.name} at=${node.location.index} ruleOrdinal=${source.id.ordinal} scope=${core.scope}"
                                        if (watch) {
                                            println("${tag}_IN run=${config.index} $where site=${at.site} ${packet(premise, facts)}")
                                            for ((i, leaf) in source.predicate.leaves.withIndex()) {
                                                val check = shared.ops.checkMark(facts, leaf, config.mode)
                                                val result = when (check) {
                                                    is MarkCheck.Holds -> "HOLDS:${check.facts.layer}"
                                                    is MarkCheck.Request -> "REQUEST:${shared.ap.marks.name(check.mark)}"
                                                    MarkCheck.None -> "NONE"
                                                }
                                                println("${tag}_LEAF run=${config.index} $where leaf=$i ${fact(leaf.fact)} check=$result " +
                                                    "permission=${source.actions.map { config.seeds.allowsSource(core.key,node,source.transfer(leaf,it,multi=true).forward,it.id) }}")
                                            }
                                        }
                                        actual.sourcePredicateActionsAt(source,premise,facts,node,statementEdge,at) { pr, value, action ->
                                            if (watch) println("${tag}_OUT run=${config.index} $where action=$action ${packet(pr,value)}")
                                            sink(pr,value,action)
                                        }
                                    }
                                    override fun checkSinksAt(premise: PremiseKey, node: CommonInst, facts: Facts,
                                        sinks: List<SinkRule>, at: OperationInput): Triggers {
                                        val result = actual.checkSinksAt(premise,node,facts,sinks,at)
                                        if (selected(core.key) && node.location.index == 32 && relevant(facts))
                                            println("ENGINE_SINK32 run=${config.index} scope=${core.scope} ${packet(premise,facts)} " +
                                                "fired=${result.fired.map { it.first.rule.id to it.second }}")
                                        return result
                                    }
                                    override fun freeze() {
                                        if (selected(core.key)) println("ENGINE_INITIALS run=${config.index} method=${core.key.method.name} scope=${core.scope} " +
                                            "initials=${core.initials.all().map { fact(it.toPattern().fact) }}")
                                        if (selected(core.key)) {
                                            val layout = state.contexts.blockLayout(core.key)
                                            println("ENGINE_LAYOUT_SCOPE run=${config.index} method=${core.key.method.name} scope=${core.scope} " +
                                                "kind=${layout[core.scope.block].kind} owns=${layout[core.scope.block].instructions}")
                                            val wanted = setOf(1,6,7,12,13,15,16,17,18,21,22,25,26,30,31,32)
                                            val method = core.key.method as JIRMethod
                                            for (inst in method.instList.instructions) if (inst.location.index in wanted &&
                                                layout.ownerOf(inst.location.index) == core.scope.block) {
                                                for ((pr,f) in core.edges.edgesAt(inst)) if (relevant(f))
                                                    println("ENGINE_POST_POINT run=${config.index} method=${method.name} scope=${core.scope} " +
                                                        "at=${inst.location.index} ${packet(pr,f)}")
                                            }
                                            val actor = probeActors[core.key]
                                            if (actor != null) {
                                                val methodView = actor.javaClass.declaredMethods.single { it.name.startsWith("forEachJoinedLocalInput") }
                                                    .also { it.isAccessible = true }
                                                val visit: (Any, Facts) -> Unit = { link, f ->
                                                    val pr = link.javaClass.getMethod("getOriginal").invoke(link) as PremiseKey
                                                    if (relevant(f)) println("ENGINE_LOCAL_INPUT run=${config.index} method=${method.name} " +
                                                        "scope=${core.scope} link=$link ${packet(pr,f)}")
                                                }
                                                methodView.invoke(actor,core.scope,visit)
                                            }
                                        }
                                        actual.freeze()
                                    }
                                }
                            }
                            val calls = MethodCallServicesFactory { core ->
                                val actual = RunMethodCallServices(core)
                                object : MethodCallServices by actual {
                                    override fun process(item: EdgeDelta) {
                                        if (selected(core.key)) {
                                            currentPoint.set("method=${core.key.method.name} at=${item.node.location.index} scope=${core.scope}")
                                            if (relevant(item.facts)) println("ENGINE_CALL_INPUT run=${config.index} current=${currentPoint.get()} ${packet(item.premise,item.facts)}")
                                        }
                                        actual.process(item)
                                    }
                                }
                            }
                            val handlers = RunMethodHandlers(local, calls)
                            val handlerFactory = RunnerHandlerFactory<RunMethodAnalyzer> { port ->
                                fun requests(label: String, method: MethodKey, rows: RequestRows) {
                                    if (!selected(method)) return
                                    for ((slot,marks) in rows) marks.forEachMark { mark ->
                                        if (state.ap.marks.name(mark).startsWith(RULE + ";")) println("ENGINE_REQUEST_EVENT $label run=${config.index} " +
                                            "method=${method.method.name} origin=${fact(slot.initial(state.ap).toPattern().fact)} mark=${state.ap.marks.name(mark)}")
                                    }
                                }
                                handlers.create(object : RunnerPort<RunMethodAnalyzer> by port {
                                    override fun send(event: RunEvent): Boolean {
                                        when (event) {
                                            is RunEvent.MarkRequestsIn -> requests("SEND_MARK",event.method,event.rows)
                                            is RunEvent.ChangedRequests -> requests("SEND_CHANGED",event.callee,event.rows)
                                            else -> Unit
                                        }
                                        return port.send(event)
                                    }
                                    override fun post(event: RunEvent.ChangedRequests): Boolean {
                                        requests("POST_CHANGED",event.callee,event.rows)
                                        return port.post(event)
                                    }
                                    override val onCut: ((Cut,Facts) -> Unit) = { cut,f ->
                                        if (currentPoint.get()?.contains("method=") == true && relevant(f))
                                            println("ENGINE_CUT_OUTPUT run=${config.index} cut=$cut current=${currentPoint.get()} layer=${f.layer} " +
                                                "facts=${state.ops.leaves(f).map { fact(it.fact) }.toList()}")
                                        port.onCut?.invoke(cut,f)
                                    }
                                    override fun subscribe(sub: Subscription) {
                                        if (selected(sub.callee)) println("ENGINE_OFFER run=${config.index} callee=${sub.callee.method.name} " +
                                            "caller=${sub.ref.caller.method.name} call=${sub.ref.call.location.index} scope=${sub.ref.scope} " +
                                            "zeroOnly=${sub.zeroOnly} ${packet(sub.ref.premise,sub.added)}")
                                        port.subscribe(sub)
                                    }
                                    override val onProcess: ((MethodKey, EdgeDelta) -> Unit) = { key, delta ->
                                        if (selected(key)) {
                                            probeActors.putIfAbsent(key,port.analyzer(key))
                                            currentPoint.set("method=${key.method.name} at=${delta.node.location.index}")
                                        } else currentPoint.remove()
                                        if (selected(key) && relevant(delta.facts)) println("ENGINE_PROCESS run=${config.index} method=${key.method.name} " +
                                            "at=${delta.node.location.index} ${packet(delta.premise,delta.facts)}")
                                        port.onProcess?.invoke(key,delta)
                                    }
                                })
                            }
                            val result = RunManager(config,state,handlerFactory).run(timeout)
                            println("ENGINE_JOINED run=${config.index} status=${result.status} methods=${result.analyzers.size}")
                            for (actor in result.analyzers.filter { selected(it.key) }) {
                                println("ENGINE_SOURCE_HITS run=${config.index} method=${actor.key.method.name} hits=${actor.sourceHits?.occurrences()?.toList()}")
                                for ((pr,f) in actor.summaries.all()) if (relevant(f))
                                    println("ENGINE_SUMMARY run=${config.index} method=${actor.key.method.name} ${packet(pr,f)}")
                                val rowsMethod = actor.javaClass.declaredMethods.single { it.name.startsWith("normalContributorRows") }.also { it.isAccessible = true }
                                @Suppress("UNCHECKED_CAST")
                                val rows = rowsMethod.invoke(actor) as Sequence<NormalRuleContributorRow>
                                cache("CURRENT",config.index,rows.asIterable())
                                val blocksView = actor.javaClass.declaredMethods.single { it.name.startsWith("blockSummaries") }
                                    .also { it.isAccessible = true }
                                @Suppress("UNCHECKED_CAST")
                                val blocks = blocksView.invoke(actor) as Sequence<ScopedRunSummary>
                                for (block in blocks) for ((pr,f) in block.summaries.all()) if (relevant(f))
                                    println("ENGINE_BLOCK_SUMMARY run=${config.index} method=${actor.key.method.name} scope=${block.key.scope} " +
                                        "exit=${block.key.exit} ${packet(pr,f)}")
                            }
                            result
                        }
                        val guardMethod = Class.forName("org.opentaint.dataflow.bidi.driver.IterationDriverKt")
                            .declaredMethods.single { it.name == "withBarrierGuard" }.also { it.isAccessible = true }
                        val guard: (SharedObjects, () -> Next) -> Next = { state, body -> unwrap { guardMethod.invoke(null,state,body) } as Next }
                        val rawDuration = Duration::class.java.getDeclaredMethod("unbox-impl").invoke(budget)
                        val ctor = IterationDriver::class.java.declaredConstructors.single { it.parameterCount == 5 }.also { it.isAccessible = true }
                        (unwrap { ctor.newInstance(policy,shared,rawDuration,invoke,guard) } as IterationDriver).also { driver = it }
                    }
                    val ctor = JIRBidiAnalysis::class.java.declaredConstructors.single { it.parameterCount == 8 }.also { it.isAccessible = true }
                    val actual = unwrap { ctor.newInstance(cp,graph,units,rules,params,FixedLimits(listOf(1,1,2,3,4)),refManager,factory) } as JIRBidiAnalysis
                    return object : BidiEntry by actual {
                        override fun run(budget: Duration): Report = actual.run(budget).also { report = it }
                    }
                }
            }
            analyzer.use {
                val (output,status) = it.analyzeWithIfds(listOf(root))
                println("ENGINE_FINAL status=$status reportEnd=${report?.end}")
                println("ENGINE_FRONTIERS ${driver?.frontiers}")
                for (v in output) println("ENGINE_FINDING rule=${v.vulnerability.ruleId} statement=${v.vulnerability.statement}")
                val selectedEntries = report?.entries.orEmpty().filter { it.descriptor.key.ruleId == RULE }
                println("ENGINE_TRUST_REPORT ${selectedEntries.map { it.descriptor.key }}")
            }
        }
    }
}

