            val dataMark = trustMarks.single { manager.marks.name(it) == ruleId + ";0;_<T>_;" }
            fun fact(f: PathFact): String = "${f.base}${f.path.map(manager.accessors::accessor)}:${f.tail}:" +
                when (val mark = f.mark) {
                    is MarkSlot.Concrete -> manager.marks.name(mark.mark)
                    else -> mark.toString()
                }
            fun edge(me: MicroEdge): String = "${fact(me.edge.from)} -> ${fact(me.edge.to)} " +
                "forward=${fact(me.forward.from)}->${fact(me.forward.to)} " +
                "may=${me.may} source=${me.isSource} identity=${me.isIdentity} conjunctive=${me.conjunctive} action=${me.actionId}"
            fun filter(label: String, base: Any, f: TypeFilter) {
                println("FILTER $label base=$base mayClass=${f.may.javaClass.name} primitivePolicy=${f.markPolicy != null}")
                f.markPolicy?.let { policy ->
                    for (mark in trustMarks) println("PRIMITIVE $label base=$base mark=${manager.marks.name(mark)} " +
                        "root=${policy.keeps(mark, 0)} element=${policy.keeps(mark, 1)}")
                }
            }
            fun summary(label: String, s: StatementSummary, statementEdge: Boolean = false) {
                println("SUMMARY $label touched=${s.touched} targets=${s.targets} staticOperations=${s.staticOperations}")
                s.typeFilters.forEach { (b, f) -> filter("$label/operand", b, f) }
                s.resultFilters.forEach { (b, f) -> filter("$label/result", b, f) }
                s.edges.forEach { println("EDGE $label ${edge(it)}") }
                // Execute only scalar ordinary AP edges, without an engine. This
                // confirms BaseOnly dollar input does not become ANY/DEMAND just
                // because it traverses a parsed CopyAllMarks library model.
                for (me in s.edges) {
                    if (me.edge.from.base != org.opentaint.dataflow.ap.ifds.AccessPathBase.This &&
                        me.edge.from.base != org.opentaint.dataflow.ap.ifds.AccessPathBase.Argument(0)) continue
                    val inputFact = PathFact(me.edge.from.base, emptyList(), Tail.EXACT, MarkSlot.Concrete(dataMark))
                    val rawInput = manager.factsOf(inputFact, ExclusionSet.Empty, Layer.NORMAL)
                    val operandFilter = s.typeFilters[rawInput.base]
                    val filtered = if (operandFilter == null) rawInput else ops.filter(rawInput, operandFilter)
                    if (filtered == null) {
                        println("SCALAR_DATA_PROBE $label operand filter rejected dollar DATA")
                        continue
                    }
                    val premise = manager.initial(Pattern(inputFact, ExclusionSet.Empty))
                    val results = arrayListOf<String>()
                    ops.applyEdge(filtered, premise, me.edge, statementEdge,
                        ApMode(true, Direction.FORWARD, 1, MarkMode.FULL), object : ApOut {
                            override fun result(f: Facts) {
                                val resultFilter = s.resultFilters[f.base]
                                val result = if (resultFilter == null) f else ops.filter(f, resultFilter)
                                if (result == null) {
                                    results += "RESULT_FILTER_REJECTED"
                                    return
                                }
                                results += "layer=${result.layer} ${ops.leaves(result).map { fact(it.fact) }.toList()}"
                            }
                            override fun markRequest(mark: TaintMark) { results += "REQUEST ${manager.marks.name(mark)}" }
                        }, may = me.may, ruleAssignment = me.isSource || me.actionId != null)
                    println("SCALAR_DATA_PROBE $label statementEdge=$statementEdge edge=${edge(me)} outputs=$results")
                }
                s.conjunctions.forEach { c -> println("CONJUNCTION $label ${c.literals.map { fact(it.fact) }} -> ${fact(c.target)}") }
                for (source in s.sources) {
                    println("SOURCE $label id=${source.id} backward=${source.backward} groups=${source.groupTransfers} " +
                        "nodes=${source.predicate.nodeCount} root=${source.predicate.root} " +
                        "unaryTransfers=${source.unaryTransfers.size} multiPredicate=${source.multiPredicate != null}")
                    if (source.predicate.leaves.indices.any(source.predicate::isMulti))
                        println("SOURCE_MULTI_LAYER $label forward joins emit targetTree(action.target,combination.layer); " +
                            "transfer.may=true describes independent reverse demand/permission transfers, not forward join demotion")
                    for ((index, leaf) in source.predicate.leaves.withIndex()) {
                        println("LEAF $label ordinal=$index ${fact(leaf.fact)} unary=${source.predicate.isUnary(index)} " +
                            "multi=${source.predicate.isMulti(index)} touched=${leaf.fact.base in s.touched}")
                        for (action in source.actions) {
                            if (source.predicate.isUnary(index)) println("TRANSFER $label unary ${edge(source.transfer(leaf, action))}")
                            if (source.predicate.isMulti(index)) println("TRANSFER $label multi ${edge(source.transfer(leaf, action, multi = true))}")
                        }
                    }
                    for (action in source.actions) println("ACTION $label id=${action.id} target=${fact(action.target)} " +
                        "touched=${action.target.base in s.touched}")
                }
            }
            val owner = checkNotNull(cp.findClassOrNull("org.owasp.benchmark.testcode.BenchmarkTest01875"))
            val interesting = setOf("getCookies", "getName", "equals", "getValue", "decode", "doSomething",
                "getSession", "setAttribute", "encoder", "encodeForHTML")
            for (method in owner.declaredMethods.filter { it.name in setOf("doPost", "doSomething") }) {
                val entry = epResolver.resolveEntryPoints(method, EmptyMethodContext).single()
                val key = MethodEntryPoint(EmptyMethodContext, entry)
                val forms = interpreter.forms(key)
                println("METHOD ${method.enclosingClass.name}#${method.name}${method.description}")
                println("BLOCK_LAYOUT ${entries[method].blockLayout}")
                for (inst in method.instList.instructions) {
                    println("JIR index=${inst.location.index} $inst")
                    val call = inst.callExpr
                    if (call == null) {
                        summary("${method.name}:${inst.location.index}/statement", forms.statement(Direction.FORWARD, inst))
                        continue
                    }
                    if (call.method.method.name !in interesting) continue
                    println("CALL index=${inst.location.index} target=${call.method.method} returnType=${call.type}")
                    for (all in listOf(false, true)) for ((ordinal, rule) in rules.sourceRulesForMethod(call.method.method, inst, null, all).withIndex())
                        println("BOUND_SOURCE allRelevant=$all ordinal=${rule.ruleOrdinal(ordinal)} serialized=${rule.serializedId} " +
                            "condition=${rule.condition} actions=${rule.actionsAfter} reset=${rule.resetMarks()}")
                    println("BOUND_PASS ${rules.passTroughRulesForMethod(call.method.method, inst, null).toList()}")
                    val plan = forms.call(Direction.FORWARD, inst, call)
                    println("PLAN touched=${plan.touched} passReads=${plan.passReads} zeroCanReturn=${plan.zeroCanReturn} " +
                        "sinks=${plan.sinks.map { it.occurrenceId }}")
                    for (base in plan.touched) println("FOOTPRINT base=$base forward=${forms.isBaseRelevant(Direction.FORWARD, inst, base, RuleView.FULL)} " +
                        "backward=${forms.isBaseRelevant(Direction.BACKWARD, inst, base, RuleView.FULL)}")
                    for ((ordinal, stage) in plan.stages.withIndex()) {
                        val label = "${method.name}:${inst.location.index}/stage$ordinal"
                        println("STAGE $label ${stage.from}->${stage.to} class=${stage.javaClass.simpleName}")
                        when (stage) {
                            is CallStage.Edges -> {
                                println("STAGE_EDGE $label kind=${stage.kind} statementEdges=${stage.kind.statementEdges} " +
                                    "guard=${stage.guard} trigger=${stage.trigger?.occurrenceId}")
                                summary(label, stage.summary, stage.kind.statementEdges)
                            }
                            is CallStage.Actions -> for ((step, clean) in stage.steps.withIndex()) when (clean) {
                                is CleanStep.Clean -> println("CLEAN $label step=$step base=${clean.cleaner.base} path=${clean.cleaner.path?.toList()} " +
                                    "reach=${clean.cleaner.reach} mark=${clean.cleaner.mark?.let(manager.marks::name)}")
                                is CleanStep.Kill -> summary("$label/kill$step", clean.keepEdges)
                                is CleanStep.Field -> {
                                    println("FIELD_CLEAN $label step=$step temp=${clean.temporary} reach=${clean.cleaner.reach} " +
                                        "mark=${clean.cleaner.mark?.let(manager.marks::name)}")
                                    summary("$label/read$step", clean.read); summary("$label/write$step", clean.write)
                                }
                            }
                            is CallStage.Callees -> println("CALLEES $label ${stage.callees}")
                            is CallStage.Predefined -> summary("$label/predefined", stage.summary)
                        }
                    }
                }
            }
        }
    }
}

